const KONTUR = '#1d1b1a';
const ton = (K, f) => (f > 0 ? hell(K.c, f) : f < 0 ? dunkel(K.c, -f) : K.c);

export function b25Zeichner(S, t, p) {
  const D = B25_DATEN[p.b25];
  if (!D) return;
  const mf = p.muster && p.muster !== 'uni' && istMuster(p.muster);
  if (!S.tex && mf) S.tex = musterFuellung(S, p.muster);
  // Bildmuster als Musterfeld-Zone: Standarddessin aus dem B-Bild (z. B. Vichy-Karo), solange das Musterfeld nichts anderes setzt
  else if (!S.tex && D.dessin && !(p.muster === 'uni')) S.tex = musterFuellung(S, D.dessin);
  const K = [S];
  const n = 1 + Math.max(0, ...D.regionen.filter((r) => r[0] === 't' || r[0] === 'r' || r[0] === 'm').map((r) => r[1]));
  for (let i = 1; i < n; i++) K.push(materialDefs(p.farben?.[i - 1] ?? 'grau', p.materialien?.[i - 1] ?? 'baumwolle', S.defs));
  // glatte Strickfläche wie B01: Maschenstruktur aus stoff.js weg, solange kein Musterfeld gesetzt ist
  if (p.glatt && !mf) K.forEach((k) => { if (k.m === 'strick' || k.m === 'kaschmir' || k.m === 'merino') k.tex = null; });
  let rip = null;
  if (D.regionen.some((r) => r[0] === 'r')) { rip = S.id + 'rp'; S.defs.push(`<pattern id="${rip}" width="1.15" height="4" patternUnits="userSpaceOnUse"><rect width="0.45" height="4" fill="#000" opacity="0.28"/><rect x="0.5" width="0.25" height="4" fill="#fff" opacity="0.08"/></pattern>`); }
  const clip = S.id + 'b25';
  S.defs.push(`<clipPath id="${clip}"><path d="${D.kontur}" fill-rule="evenodd"/></clipPath>`);
  t.push(`<ellipse cx="50" cy="${D.boden + 1.8}" rx="${Math.min(32, D.breite * 0.45).toFixed(1)}" ry="2.4" fill="#000" opacity="0.08"/>`);
  t.push(`<g clip-path="url(#${clip})">`);
  for (const r of D.regionen) {
    const d = r[r.length - 1];
    if (r[0] === 'k') t.push(`<path d="${d}" fill="${KONTUR}"/>`);
    else if (r[0] === 'f') t.push(`<path d="${d}" fill="${r[1]}"/>`);
    else if (r[0] === 'r') { const k = K[r[1]]; t.push(`<path d="${d}" fill="${ton(k, r[2])}"/>`); if (k.tex) t.push(`<path d="${d}" fill="${k.tex}"/>`); t.push(`<path d="${d}" fill="url(#${rip})"/>`); }
    else {
      const k = r[0] === 'm' && mf ? K[0] : K[r[1]], f = r[0] === 'm' && mf ? Math.min(0, r[2]) * 0.5 : r[2];
      t.push(`<path d="${d}" fill="${ton(k, f)}"/>`); if (k.tex) t.push(`<path d="${d}" fill="${k.tex}"/>`);
    }
  }
  // Licht von links wie alle Stoffe (stoff.js), Glanz bei Leder, Lack, Nylon
  t.push(`<path d="${D.kontur}" fill="url(#${S.id}l)" fill-rule="evenodd"/>`);
  if (S.glanz) t.push(`<path d="${D.kontur}" fill="url(#${S.id}g)" fill-rule="evenodd"/>`);
  t.push('</g>');
}
